<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: #121a31;
        --panel-2: #17213d;
        --border: #2a3558;
        --text: #edf2ff;
        --muted: #aab5d6;
        --accent: #7c9cff;
        --accent-strong: #98b0ff;
        --danger: #ff7a8a;
        --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
      }

      * {
        box-sizing: border-box;
      }

      html,
      body {
        min-height: 100%;
      }

      body {
        margin: 0;
        font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 34%),
          linear-gradient(180deg, #0b1020 0%, #09101d 100%);
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 40rem);
        padding: clamp(1.25rem, 3vw, 2rem);
        border: 1px solid rgba(138, 156, 214, 0.2);
        border-radius: 1.25rem;
        background: linear-gradient(180deg, rgba(18, 26, 49, 0.98), rgba(11, 16, 32, 0.98));
        box-shadow: var(--shadow);
      }

      h1 {
        margin: 0 0 0.5rem;
        font-size: clamp(1.7rem, 3vw, 2.3rem);
        line-height: 1.1;
        letter-spacing: -0.03em;
      }

      .lede {
        margin: 0 0 1.5rem;
        color: var(--muted);
      }

      .form-field {
        margin: 0;
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-width: 0;
      }

      legend {
        padding: 0;
        margin-bottom: 0.5rem;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .required-mark {
        color: var(--accent-strong);
      }

      .help-text,
      .field-error,
      .form-status {
        margin: 0.35rem 0 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .field-error {
        display: none;
        color: var(--danger);
      }

      fieldset[aria-invalid="true"] .field-error {
        display: block;
      }

      .options {
        display: grid;
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .option {
        display: flex;
        align-items: center;
        gap: 0.85rem;
        padding: 1rem 1.1rem;
        border: 1px solid var(--border);
        border-radius: 0.95rem;
        background: rgba(23, 33, 61, 0.9);
        cursor: pointer;
        transition:
          border-color 150ms ease,
          background-color 150ms ease,
          transform 150ms ease;
      }

      .option:hover {
        border-color: rgba(124, 156, 255, 0.75);
        background: rgba(29, 40, 73, 0.96);
      }

      .option:focus-within {
        border-color: var(--accent);
        box-shadow: 0 0 0 3px rgba(124, 156, 255, 0.24);
      }

      .option input {
        width: 1.15rem;
        height: 1.15rem;
        margin: 0;
        accent-color: var(--accent);
        flex: none;
      }

      .option span {
        font-weight: 600;
      }

      .actions {
        margin-top: 1.5rem;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 0.9rem;
        padding: 0.9rem 1.2rem;
        font: inherit;
        font-weight: 700;
        color: #07101f;
        background: linear-gradient(180deg, #a8bcff, #7c9cff);
        box-shadow: 0 10px 24px rgba(124, 156, 255, 0.25);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.04);
      }

      button:focus-visible,
      .option input:focus-visible {
        outline: 3px solid #e9edff;
        outline-offset: 3px;
      }

      .form-status {
        min-height: 1.5em;
        margin-top: 1rem;
        color: var(--accent-strong);
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      @media (max-width: 480px) {
        .card {
          border-radius: 1rem;
        }

        .option {
          align-items: flex-start;
        }
      }
    </style>
  </head>
  <body>
    <main id="maincontent">
      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Notification preferences</h1>
        <p class="lede">Choose one way we should send updates and alerts.</p>

        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset id="notification-group" aria-describedby="notification-help notification-error">
              <legend>How do you prefer to receive notifications? <span class="required-mark" aria-hidden="true">*</span></legend>
              <p id="notification-help" class="help-text">Select one option before continuing.</p>
              <p id="notification-error" class="field-error" aria-live="polite"></p>

              <div class="options">
                <label class="option">
                  <input type="radio" name="notification-method" value="Email" required>
                  <span>Email</span>
                </label>

                <label class="option">
                  <input type="radio" name="notification-method" value="SMS" required>
                  <span>SMS</span>
                </label>

                <label class="option">
                  <input type="radio" name="notification-method" value="Push Notifications" required>
                  <span>Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Save preferences</button>
          </div>

          <p id="form-status" class="form-status" role="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const group = document.getElementById("notification-group");
      const error = document.getElementById("notification-error");
      const status = document.getElementById("form-status");
      const radios = Array.from(form.elements["notification-method"]);

      function setGroupError(message) {
        group.setAttribute("aria-invalid", "true");
        error.textContent = message;
      }

      function clearGroupError() {
        group.removeAttribute("aria-invalid");
        error.textContent = "";
      }

      function getSelectedValue() {
        const selected = radios.find((radio) => radio.checked);
        return selected ? selected.value : "";
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const selectedValue = getSelectedValue();

        if (!selectedValue) {
          setGroupError("Error: Choose Email, SMS, or Push Notifications.");
          status.textContent = "";
          radios[0].focus();
          return;
        }

        clearGroupError();
        status.textContent = `${selectedValue} selected. Your preference has been saved.`;
      });

      radios.forEach((radio) => {
        radio.addEventListener("change", () => {
          if (getSelectedValue()) {
            clearGroupError();
          }
        });
      });
    </script>
  </body>
</html>
