        border-radius: 0.9rem;
        padding: 0.9rem 1.2rem;
        font: inherit;
        font-weight: 700;
        color: #07101f;
        background: linear-gradient(180deg, #a8bcff, #7c9cff);
        box-shadow: 0 10px 24px rgba(124, 156, 255, 0.25);
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.04);
      }

      button:focus-visible,
      .option input:focus-visible {
        outline: 3px solid #e9edff;
        outline-offset: 3px;
      }

      .form-status {
        min-height: 1.5em;
        margin-top: 1rem;
        color: var(--accent-strong);
      }

