     <a class="skip-link" href="#maincontent">Skip to main content</a>
     <main id="maincontent" tabindex="-1">
       <section class="card" aria-labelledby="page-title">
         <h1 id="page-title">Notification preferences</h1>
         <p class="lede">Choose one way we should send updates and alerts.</p>

         <form id="notification-form" novalidate>
           <div class="form-field">
             <fieldset id="notification-group" aria-describedby="notification-help notification-error">
               <legend>How do you prefer to receive notifications? <span class="required-mark" aria-hidden="true">*</span></legend>
               <p id="notification-help" class="help-text">Select one option before continuing.</p>
               <p id="notification-error" class="field-error" aria-live="polite"></p>

               <div class="options">
                 <label class="option">
                   <input type="radio" name="notification-method" value="Email" required>
                   <span>Email</span>
                 </label>

                 <label class="option">
                   <input type="radio" name="notification-method" value="SMS" required>
                   <span>SMS</span>
                 </label>

                 <label class="option">
                   <input type="radio" name="notification-method" value="Push Notifications" required>
                   <span>Push Notifications</span>
                 </label>
               </div>
             </fieldset>
           </div>

           <div class="actions">
             <button type="submit">Save preferences</button>
           </div>

           <p id="form-status" class="form-status" role="status" aria-live="polite"></p>
         </form>
       </section>
