       const form = document.getElementById("notification-form");
       const group = document.getElementById("notification-group");
       const error = document.getElementById("notification-error");
       const status = document.getElementById("form-status");
       const radios = Array.from(form.elements["notification-method"]);

       function setGroupError(message) {
         group.setAttribute("aria-invalid", "true");
         error.textContent = message;
       }

       function clearGroupError() {
         group.removeAttribute("aria-invalid");
         error.textContent = "";
       }

       function getSelectedValue() {
         const selected = radios.find((radio) => radio.checked);
         return selected ? selected.value : "";
       }

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const selectedValue = getSelectedValue();

         if (!selectedValue) {
           setGroupError("Error: Choose Email, SMS, or Push Notifications.");
           status.textContent = "";
           radios[0].focus();
           return;
         }

         clearGroupError();
         status.textContent = `${selectedValue} selected. Your preference has been saved.`;
       });

       radios.forEach((radio) => {
         radio.addEventListener("change", () => {
           if (getSelectedValue()) {
             clearGroupError();
           }
